mapper.select:
SELECT COUNT(1)
FROM book
WHERE user_id = #{userId} AND file_name = #{fileName}

mapper.update:
UPDATE book
SET status = #{status}, update_time = NOW()
WHERE id = #{id}

UPDATE book
SET status = #{toStatus}, update_time = NOW()
WHERE id = #{id} AND status = #{fromStatus}

mapper.delete:
DELETE FROM book
WHERE id = #{id}
  AND user_name = #{userName}
